/* Cyrillic Yo/yo: UTF-8 0xD0 0x81 and 0xD1 0x91 */
static const uint8_t font_cyr_yo_cap[16] = {0x24, 0x00, 0x3F, 0x20, 0x20, 0x20, 0x3F, 0x20, 0x20, 0x20, 0x20, 0x3F, 0x00, 0x00, 0x00, 0x00}; /* Ё */
