static inline const uint8_t* get_cyrillic_glyph(uint8_t b1, uint8_t b2) {
    if (b1 == 0xD0) {
        if (b2 >= 0x90 && b2 <= 0xBF) return &font_cyr_d0[b2 - 0x90][0];
        if (b2 == 0x81) return font_cyr_yo_cap;
    } else if (b1 == 0xD1) {
        if (b2 >= 0x80 && b2 <= 0x8F) return &font_cyr_d1[b2 - 0x80][0];
        if (b2 == 0x91) return font_cyr_yo_sml;
    }
    return &font_ascii[0][0];
}

